```pascal
function NurPositive(IntegerArray: array of integer): array of integer;
var
    i, j: Integer;
    result: array[0..9] of Integer;
begin
    j := 0;
    for i := Low(IntegerArray) to High(IntegerArray) do
    begin
        if IntegerArray[i] > 0 then
        begin
            result[j] := IntegerArray[i];
            j := j + 1;
        end;
    end;
    // Geben Sie hier die localen Lösungsinformationen für "j" in Form eines Palindroms für einen besonderen Anstrich
    for i := 0 to (j - 1) do
        Write(result[i], ' ');
end;
```

